import "server-only";
import { notFound } from "next/navigation";
import { currentUser } from "@/lib/auth";
import { dedicatedPublicEnabled, requireDedicatedAccess } from "@/lib/dedicated/gate";
import { loadOrderCatalog, orderPreviewAll, type OrderCatalogCard } from "@/lib/dedicated/order";
import { cpuBrandOf, gpuBrandOf } from "@/lib/dedicated/brand";
import { NX_FAMILIES, NX_FAMILY_INFO } from "@/lib/dedicated/nx-names";
import { TAG_LABEL, TAG_RULE } from "@/lib/dedicated/tags";
import { flagSvg } from "@/lib/dedicated/flags";
import { bareMetalHeroSvg } from "@/lib/dedicated/hero-art";
import { DEDICATED_COUNTRY_PAGES, dedicatedCountryPage, dedicatedCountryPath } from "@/lib/dedicated/regions";
import { APP_URL } from "@/components/marketing/StructuredData";
import { esc, usd, type NxmLoad } from "./lib";

/**
 * /dedicated-servers (Bare Metal Dedicated Servers) and its country pages
 * /dedicated-servers/<country> — the NXM pages. GATED: 404 unless the
 * dedicated gate passes (Setting dedicated_public_enabled, or a private-
 * preview account; lib/dedicated/gate.ts). noindex unless public; the sitemap
 * lists them only when public (lib/sitemap-sections.ts EXCLUDE + dedicatedSitemapPaths).
 *
 * Every figure is real: the same in-stock catalogue + pricing rules the
 * checkout charges (lib/dedicated/order.ts), the NX names and tags the portal
 * shows. Buy links go straight into the portal flow; a signed-out visitor is
 * sent through /register?next=. No reviews, ratings or invented stats.
 */
const FLOW = "/dashboard/dedicated";

async function inStockCards(): Promise<OrderCatalogCard[]> {
  const access = await requireDedicatedAccess();
  const cards = await loadOrderCatalog(await orderPreviewAll(access.preview));
  anyGpuListed = cards.some((c) => !!c.gpu);
  return cards.filter((c) => c.regions.some((r) => r.inStock));
}
/** Whether the catalogue lists any GPU build at all (in stock or not), for the hero's NVIDIA mark. */
let anyGpuListed = false;

export async function meta(p: Record<string, string>) {
  const on = await dedicatedPublicEnabled();
  const page = p.country ? dedicatedCountryPage(p.country) : null;
  if (page) {
    return {
      title: `Bare Metal Dedicated Servers in ${page.name}`,
      description: `Bare metal dedicated servers in ${page.inName}: single-tenant AMD and Intel hardware with full root, your own IPv4, DDoS protection and reboot, rescue and reinstall from your dashboard. Live stock and monthly prices.`,
      noindex: !on,
      canonical: dedicatedCountryPath(page.slug),
    };
  }
  return {
    title: "Bare Metal Dedicated Servers",
    description: "Bare metal dedicated servers with full root, your own IPv4, DDoS protection and reboot, rescue and reinstall from your dashboard. AMD EPYC, Ryzen and Intel Xeon builds, live stock, monthly prices.",
    noindex: !on,
  };
}

const keyOf = (label: string) => label.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const logoImg = (b: string, h: number, alt: string) => `<img src="/nxm/home/logos-${b}.svg" alt="${alt}" style="height:${h}px !important;width:auto !important">`;

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const all = await inStockCards();
  const page = p.country ? dedicatedCountryPage(p.country) : null;
  if (p.country && !page) notFound();
  const inCountry = (c: OrderCatalogCard) => !page || c.regions.some((r) => r.inStock && r.country === page.country);
  const cards = all.filter(inCountry);
  if (page && cards.length === 0) notFound(); // nothing offered there: no thin page
  const user = await currentUser();
  const hrefFor = (id: string, region?: string) => {
    const q = new URLSearchParams({ build: id });
    if (region) q.set("region", region);
    const dest = `${FLOW}?${q.toString()}`;
    return user ? dest : `/register?next=${encodeURIComponent(dest)}`;
  };
  const regionsOf = (c: OrderCatalogCard) => c.regions.filter((r) => r.inStock && (!page || r.country === page.country));
  const fromOf = (c: OrderCatalogCard) => Math.min(...regionsOf(c).map((r) => r.fromMonthlyCents));
  const sorted = [...cards].sort((a, b) => fromOf(a) - fromOf(b));
  const cheapest = sorted[0] ?? null;

  // locations, grouped by customer label; several region codes can share one label
  const regions = new Map<string, { code: string; label: string; area: string; country: string; inStock: number; listed: number }>();
  for (const c of all) {
    const seen = new Map<string, boolean>();
    for (const r of c.regions) seen.set(keyOf(r.label), (seen.get(keyOf(r.label)) ?? false) || r.inStock);
    for (const [k, inStock] of seen) {
      const r = c.regions.find((x) => keyOf(x.label) === k)!;
      const e = regions.get(k) ?? { code: k, label: r.label, area: r.area, country: r.country, inStock: 0, listed: 0 };
      e.listed++;
      if (inStock) e.inStock++;
      regions.set(k, e);
    }
  }
  const regionList = [...regions.values()].sort((a, b) => b.inStock - a.inStock || a.label.localeCompare(b.label));
  const countries = new Set(regionList.filter((r) => r.inStock).map((r) => r.country));
  const flags: Record<string, string> = {};
  for (const r of regionList) flags[r.country] = flagSvg(r.country, { width: 22 });

  const families = NX_FAMILIES.map((f) => {
    const list = sorted.filter((c) => c.family === f);
    return { f, count: list.length, from: list.length ? Math.min(...list.map(fromOf)) : null, maxCores: list.reduce((m, c) => Math.max(m, c.cores), 0) };
  }).filter((x) => x.count > 0);
  const familyIcon: Record<string, string> = { "NX-Core": "blade", "NX-Pulse": "bolt", "NX-Forge": "cpu", "NX-Titan": "server", "NX-GPU": "spark" };

  const familiesHtml = families.length
    ? `<ul class="dd-fams">${families.map((x) => `<li class="dd-fam"><span class="dd-fam-ic" data-au-icon="${familyIcon[x.f] ?? "cpu"}"></span><b>${esc(x.f)}</b><small>${esc(NX_FAMILY_INFO[x.f].short)}</small><p>${esc(NX_FAMILY_INFO[x.f].blurb)}.</p><span class="dd-fam-meta">${x.count} build${x.count === 1 ? "" : "s"} in stock · up to ${x.maxCores} cores${x.from != null ? ` · from <b>${usd(x.from)}</b>/mo` : ""}</span><button type="button" class="dd-fam-go" data-family="${esc(x.f)}">See ${esc(x.f)} builds →</button></li>`).join("")}</ul>`
    : "";

  const locations = regionList.length
    ? `<ul class="dd-locs">${regionList.map((r) => {
        const cp = DEDICATED_COUNTRY_PAGES.find((x) => x.country === r.country);
        const inner = `<span class="dd-loc-f">${flagSvg(r.country, { width: 30 })}</span><span class="dd-loc-t"><small>${esc(r.area)}</small><b>${esc(r.label)}</b><span>${r.inStock ? `${r.inStock} build${r.inStock === 1 ? "" : "s"} in stock` : "Sold out right now"}</span></span>`;
        return `<li class="dd-loc${r.inStock ? " on" : ""}">${cp && r.inStock ? `<a href="/nxm${dedicatedCountryPath(cp.slug)}">${inner}</a>` : `<div>${inner}</div>`}</li>`;
      }).join("")}</ul>`
    : `<p class="lede">Locations are being refreshed.</p>`;

  const countryLinks = DEDICATED_COUNTRY_PAGES.filter((cp) => countries.has(cp.country) && cp.slug !== page?.slug)
    .map((cp) => `<a href="/nxm${dedicatedCountryPath(cp.slug)}">${flagSvg(cp.country, { width: 18 })}<span>Bare metal in ${esc(cp.name)}</span></a>`).join("");

  const hasGpu = sorted.some((c) => c.gpu) || anyGpuListed;
  const logos =
    `<li><span class="dd-lg">${logoImg("amd", 40, "AMD Ryzen")}</span><small>Ryzen · EPYC</small></li>` +
    `<li><span class="dd-lg">${logoImg("intel", 44, "Intel")}</span><small>Xeon</small></li>` +
    (hasGpu ? `<li><span class="dd-lg">${logoImg("nvidia", 40, "NVIDIA")}</span><small>GPUs</small></li>` : "");

  const data = {
    preCountry: page?.country ?? null,
    flags,
    tagLabel: TAG_LABEL,
    tagRule: TAG_RULE,
    families: families.map((x) => x.f),
    regions: regionList.map((r) => ({ code: r.code, label: r.label, country: r.country, inStock: r.inStock })),
    cards: sorted.map((c) => ({
      id: c.id,
      name: c.name,
      family: c.family,
      familyShort: NX_FAMILY_INFO[c.family].short,
      tags: c.tags,
      href: hrefFor(c.id),
      hrefTpl: hrefFor(c.id, "__REGION__"),
      cpuShort: c.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1"),
      cpuBrand: cpuBrandOf(c.cpu),
      cpuBrandName: c.cpuBrand,
      gpu: c.gpu,
      gpuBrand: gpuBrandOf(c.gpu),
      cores: c.cores,
      threads: c.threads,
      ghz: c.boostGhz ?? c.baseGhz,
      ramGb: c.ramGb,
      maxRamGb: c.maxRamGb,
      storage: c.storage.replace(/\s*\((Soft|Hard) RAID\)/i, ""),
      raid: /\((Soft|Hard) RAID\)/i.exec(c.storage)?.[0].replace(/[()]/g, "") ?? "",
      storageGb: c.storageGb,
      bandwidth: c.bandwidth,
      setup: (c.regions.find((r) => r.inStock)?.setupCents ?? 0) / 100,
      // grouped by location label; the configure link carries a real region code that is in stock there
      regions: [...new Set(c.regions.map((r) => keyOf(r.label)))].map((k) => {
        const rs = c.regions.filter((r) => keyOf(r.label) === k);
        const best = rs.filter((r) => r.inStock).sort((a, b) => a.fromMonthlyCents - b.fromMonthlyCents)[0] ?? rs[0];
        return { code: k, region: best.code, label: best.label, country: best.country, inStock: rs.some((r) => r.inStock), from: best.fromMonthlyCents / 100 };
      }),
    })),
  };

  const prices = sorted.map(fromOf);
  const route = page ? dedicatedCountryPath(page.slug) : "/dedicated-servers";
  const name = page ? `Bare Metal Dedicated Servers in ${page.name}` : "Bare Metal Dedicated Servers";
  const jsonLd: object[] = prices.length
    ? [
        {
          "@context": "https://schema.org", "@type": "Product", name: `Nxeon ${name}`,
          description: `Single-tenant bare metal dedicated servers${page ? ` in ${page.inName}` : ""} with full root, dedicated IPv4 and DDoS protection, billed monthly or yearly.`,
          brand: { "@type": "Brand", name: "Nxeon" },
          offers: { "@type": "AggregateOffer", priceCurrency: "USD", lowPrice: (Math.min(...prices) / 100).toFixed(2), highPrice: (Math.max(...prices) / 100).toFixed(2), offerCount: prices.length, availability: "https://schema.org/InStock", url: APP_URL + route },
        },
        {
          "@context": "https://schema.org", "@type": "ItemList", name: `${name} in stock`,
          itemListElement: sorted.slice(0, 12).map((c, i) => ({
            "@type": "ListItem", position: i + 1,
            item: {
              "@type": "Product", name: `${c.name} bare metal server`, brand: { "@type": "Brand", name: "Nxeon" },
              description: `${c.cpu}, ${c.cores} cores / ${c.threads} threads, ${c.ramGb} GB RAM, ${c.storage}${c.gpu ? `, ${c.gpu}` : ""}.`,
              offers: { "@type": "Offer", priceCurrency: "USD", price: (fromOf(c) / 100).toFixed(2), availability: "https://schema.org/InStock", url: APP_URL + route + "#catalogue",
                priceSpecification: { "@type": "UnitPriceSpecification", price: (fromOf(c) / 100).toFixed(2), priceCurrency: "USD", unitCode: "MON", referenceQuantity: { "@type": "QuantitativeValue", value: 1, unitCode: "MON" } } },
            },
          })),
        },
      ]
    : [];

  return {
    slots: {
      eyebrow: page ? `Bare metal · ${page.name}` : "Bare Metal Dedicated Servers",
      "h1:html": page ? `Bare metal dedicated servers in ${esc(page.name)}. <span>Yours alone.</span>` : `Bare metal dedicated servers. <span>Yours alone.</span>`,
      lede: page
        ? `Single-tenant servers in ${page.inName} where every core, every gigabyte and every disk is yours. Full root, your own IPv4, DDoS protection, and reboot, rescue and reinstall from your dashboard. In-stock builds are online within 24 hours.`
        : "Single-tenant dedicated servers where every core, every gigabyte and every disk is yours. Full root, your own IPv4, DDoS protection, and reboot, rescue and reinstall from your dashboard. In-stock builds are online within 24 hours.",
      catTitle: page ? `Every bare metal build in stock in ${page.name}` : "Every bare metal build in stock right now",
      count: String(cards.length),
      from: cheapest ? usd(fromOf(cheapest)) : "—",
      maxCores: String(cards.reduce((m, c) => Math.max(m, c.cores), 0)),
      regions: String(page ? regionList.filter((r) => r.country === page.country && r.inStock).length : regionList.filter((r) => r.inStock).length),
      "art:html": bareMetalHeroSvg({ idPrefix: "ddh" }),
      "logos:html": logos,
      "families:html": familiesHtml,
      "locations:html": locations,
      "countries:html": countryLinks ? `<nav class="dd-countries" aria-label="Bare metal by country">${countryLinks}</nav>` : "",
      register: user ? FLOW : `/register?next=${encodeURIComponent(FLOW)}`,
    },
    data,
    crumb: "Bare metal dedicated servers",
    ...(page ? { trail: [{ name: "Bare metal dedicated servers", path: "/dedicated-servers" }, { name: page.name, path: route }] } : {}),
    jsonLd,
  };
}
