import { nxmParams } from "../_data/params";
import "../_pages/dedicated-servers/page.css";

export const dynamic = "force-dynamic";
export async function generateMetadata({ params, searchParams }: { params: Promise<Record<string, string>>; searchParams: Promise<Record<string, string | string[] | undefined>> }): Promise<Metadata> {
  const p = await nxmParams(params, searchParams, {});
  return nxmMetadata("/dedicated-servers", await meta(p));
}

export default async function Page({ params, searchParams }: { params: Promise<Record<string, string>>; searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  const p = await nxmParams(params, searchParams, {});
  const d: NxmLoad = await load(p);
  return <NxmPage slug="dedicated-servers" route={"/dedicated-servers"} body={C.BODY_HTML} attrs={C.BODY_ATTRS} particles={d.particles} slots={d.slots} data={d.data} jsonLd={d.jsonLd} crumb={d.crumb} trail={d.trail} />;
}
