  function row(c, regs, from) {
    return '<li class="dd-row"><div class="nm"><b>' + esc(c.name) + ' ' + tags(c, 1) + '</b><span>' + logo(c.cpuBrand, 11) + esc(c.cpuShort) + (c.gpu ? ' · ' + esc(c.gpu) : '') + '</span></div>' +
      '<span class="c"><b>' + esc(c.cores) + '</b> cores · ' + esc(c.threads) + 't</span>' +
      '<span class="c"><b>' + esc(c.ramGb) + ' GB</b> · ' + esc(c.storage) + '</span>' + flagsOf(regs, 4) +
      '<span class="end"><b>' + __nxmMoney(from) + '<small style="font-size:.75rem;color:var(--dd-ink3)">/mo</small></b><a class="dd-go" href="' + esc(hrefOf(c, regs)) + '">Configure</a></span></li>';
  }

  function render(resetLimit) {
    if (resetLimit) st.limit = 12;
    var rows = [];
    (D.cards || []).forEach(function (c) {
      var regs = (c.regions || []).filter(function (r) { return r.inStock && (st.regions.length === 0 || st.regions.indexOf(r.code) >= 0); });
      if (!regs.length) return;
      var from = Math.min.apply(null, regs.map(function (r) { return r.from; }));
      if (st.brands.length && !st.brands.some(function (b) { return b === 'GPU' ? !!c.gpu : c.cpuBrandName === b; })) return;
      if (st.fams.length && st.fams.indexOf(c.family) < 0) return;
