    });
    rows.sort(function (a, b) {
      return st.sort === 'price' ? a.from - b.from : st.sort === 'price-desc' ? b.from - a.from
        : st.sort === 'value' ? a.from / unit(a.c) - b.from / unit(b.c)
        : st.sort === 'cores' ? b.c.cores - a.c.cores || a.from - b.from
        : st.sort === 'ram' ? b.c.maxRamGb - a.c.maxRamGb || a.from - b.from
        : b.c.storageGb - a.c.storageGb || a.from - b.from;
    });
    document.getElementById('dd-count').innerHTML = '<b>' + rows.length + '</b> of ' + (D.cards || []).length + ' in-stock builds match';
    grid.className = 'dd-grid' + (st.view === 'list' ? ' list' : '');
    grid.innerHTML = rows.slice(0, st.limit).map(function (x) { return st.view === 'list' ? row(x.c, x.regs, x.from) : card(x.c, x.regs, x.from); }).join('');
    more.hidden = rows.length <= st.limit;
    document.getElementById('dd-empty').hidden = rows.length > 0;
    grid.hidden = rows.length === 0;
  }
  sync(); render(true);
})();

/* ================= Bare Metal Dedicated Servers (native page) =================
   Same visual language as the portal's bare-metal flow (components/dedicated/bm.css):
   neutral graphite surfaces, a clear type ramp, the violet->blue accent only where
   it carries meaning (selected state, primary action, price). */
main{overflow:clip}
.pg-dd{--dd-card:#0e131b;--dd-card2:#141a24;--dd-card3:#1a212d;--dd-line:rgba(255,255,255,.075);--dd-line2:rgba(255,255,255,.14);--dd-ink:#f3f5f9;--dd-ink2:#b9c1ce;--dd-ink3:#8a93a3;--dd-acc:#8b6cff;--dd-acc2:#4f7dff;--dd-accink:#b9a8ff;--dd-accsoft:rgba(139,108,255,.14);--dd-ok:#2fd39a;--dd-warn:#f2b84b;--dd-grad:linear-gradient(100deg,#8b6cff,#4f7dff)}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
/* hero */
.dd-hero{position:relative;padding:calc(var(--nav-h) + clamp(48px,7vw,96px)) 0 clamp(56px,7vw,96px);isolation:isolate}
.dd-sky{position:absolute;inset:0;z-index:-1;overflow:hidden}
.dd-grid-bg{position:absolute;inset:0;opacity:.5;background-image:linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px);background-size:40px 40px;-webkit-mask-image:radial-gradient(60% 70% at 72% 40%,#000,transparent 75%);mask-image:radial-gradient(60% 70% at 72% 40%,#000,transparent 75%)}
.dd-glow{position:absolute;inset:0;background:radial-gradient(46% 60% at 78% 30%,rgba(123,63,239,.30),transparent 62%),radial-gradient(40% 50% at 60% 90%,rgba(59,107,232,.22),transparent 70%),radial-gradient(40% 60% at 4% 0%,rgba(123,58,245,.18),transparent 64%)}
.dd-sky::after{content:"";position:absolute;inset:auto 0 0;height:160px;background:linear-gradient(180deg,transparent,var(--bg))}
.dd-hero-in{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:clamp(28px,4vw,64px);align-items:center}
.dd-hero h1{margin:0 0 20px;font-size:clamp(2.4rem,4.6vw,4rem);line-height:1.03;letter-spacing:-.038em;font-weight:800;text-wrap:balance;max-width:16ch}
.dd-hero h1 span{background:linear-gradient(96deg,#c3b5ff,#8fb0ff 50%,#7ce3ff);-webkit-background-clip:text;background-clip:text;color:transparent}
.dd-lede{color:var(--dd-ink2);font-size:clamp(1.02rem,1.25vw,1.13rem);line-height:1.7;max-width:56ch;margin:0 0 28px}
.dd-powered{display:flex;flex-wrap:wrap;align-items:center;gap:14px 20px;margin:32px 0 0}
.dd-powered-k{font:600 .7rem var(--f-mono);letter-spacing:.16em;text-transform:uppercase;color:var(--dd-ink3)}
.dd-logos{display:flex;flex-wrap:wrap;gap:12px;margin:0;padding:0;list-style:none}
.dd-logos li{display:flex;flex-direction:column;align-items:center;gap:8px;min-width:148px;padding:16px 22px 12px;border-radius:16px;background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.02));border:1px solid rgba(255,255,255,.1);box-shadow:inset 0 1px 0 rgba(255,255,255,.06)}
.dd-logos .dd-lg{display:flex;align-items:center;justify-content:center;height:48px}
.dd-logos img{display:block;filter:drop-shadow(0 2px 10px rgba(0,0,0,.45))}
.dd-logos small{font:600 .66rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--dd-ink2)}
.dd-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:28px 0 0;max-width:640px}
.dd-stats>div{padding:12px 14px;border-radius:14px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.08)}
.dd-stats dt{font:600 .66rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--dd-ink3)}
.dd-stats dd{margin:5px 0 0;font-size:clamp(1.2rem,1.8vw,1.55rem);font-weight:800;letter-spacing:-.03em;color:#fff;font-variant-numeric:tabular-nums}
.dd-stats dd small{font-size:.78rem;font-weight:600;color:var(--dd-ink2);letter-spacing:0}
.dd-art{margin:0;position:relative}
.dd-art svg{display:block;width:100%;height:auto;max-width:600px;margin-inline:auto}
.dd-eyebrow{display:block;margin-bottom:14px;font:600 .76rem var(--f-mono);letter-spacing:.16em;text-transform:uppercase;color:var(--dd-accink)}
/* art motion (mirrors components/dedicated/bm.css) */
.bm-art .led{animation:bm-blink 2.6s steps(1,end) infinite}.bm-art .led.l2{animation-duration:1.9s;animation-delay:-.7s}.bm-art .led.l3{animation-duration:3.3s;animation-delay:-1.4s}.bm-art .led.l4{animation-duration:1.3s;animation-delay:-.3s}
.bm-art .pkt{animation:bm-flow 3.2s linear infinite}.bm-art .pkt.p2{animation-delay:-1.1s;animation-duration:2.7s}.bm-art .pkt.p3{animation-delay:-2s;animation-duration:3.8s}
.bm-art .float{animation:bm-float 7s ease-in-out infinite;transform-box:fill-box;transform-origin:center}.bm-art .float.f2{animation-delay:-3.5s}
.bm-art .scan{animation:bm-scan 5.5s ease-in-out infinite}.bm-art .glow{animation:bm-glow 4.5s ease-in-out infinite}
@keyframes bm-blink{0%,100%{opacity:1}45%{opacity:.25}60%{opacity:1}80%{opacity:.55}}
@keyframes bm-flow{0%{stroke-dashoffset:120;opacity:0}10%{opacity:1}90%{opacity:1}100%{stroke-dashoffset:0;opacity:0}}
@keyframes bm-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
@keyframes bm-scan{0%,100%{transform:translateY(0);opacity:0}15%{opacity:.8}50%{transform:translateY(150px);opacity:.8}65%{opacity:0}}
@keyframes bm-glow{0%,100%{opacity:.55}50%{opacity:1}}
@media (prefers-reduced-motion:reduce){.bm-art .led,.bm-art .pkt,.bm-art .float,.bm-art .scan,.bm-art .glow{animation:none!important}.bm-art .pkt{stroke-dashoffset:0;opacity:.6}.bm-art .scan{opacity:0}.dd-card2{transition:none!important}}
/* sections */
.dd-sec{padding-block:clamp(64px,8vw,110px)}
.dd-tone{background:linear-gradient(180deg,transparent,rgba(14,19,30,.6) 16%,rgba(14,19,30,.6) 84%,transparent)}
.dd-head{margin-bottom:24px}
/* filter card */
.dd-filter{display:grid;gap:18px;padding:20px 22px;border-radius:22px;background:var(--dd-card);border:1px solid var(--dd-line);box-shadow:0 1px 0 rgba(255,255,255,.04) inset,0 24px 60px -36px rgba(0,0,0,.9)}
.dd-f-top{display:flex;flex-wrap:wrap;align-items:center;gap:12px}
.dd-f-title{display:flex;align-items:center;gap:12px;margin-right:auto}
.dd-f-ic{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:var(--dd-card2);border:1px solid var(--dd-line);color:var(--dd-accink)}
.dd-f-ic svg{width:17px;height:17px}
.dd-f-title b{display:block;font-size:1.02rem;color:#fff}
.dd-f-title small{display:block;font-size:.84rem;color:var(--dd-ink3)}
.dd-f-title small b{display:inline;color:#fff;font-size:inherit}
.dd-search input{height:40px;width:min(320px,70vw);border-radius:12px;border:1px solid var(--dd-line2);background:var(--dd-card2);color:#fff;padding:0 14px;font-size:.92rem;outline:none}
.dd-search input:focus{border-color:var(--dd-acc);box-shadow:0 0 0 3px var(--dd-accsoft)}
.dd-reset{height:40px;padding:0 16px;border-radius:12px;border:1px solid var(--dd-line2);background:var(--dd-card2);color:#fff;font-weight:700;font-size:.86rem;cursor:pointer}
.dd-reset:disabled{opacity:.4;cursor:default}
.dd-f-row{display:flex;flex-direction:column;gap:8px;min-width:0}
.dd-k{font:600 .68rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--dd-ink3)}
.dd-chips{display:flex;flex-wrap:wrap;gap:8px}
.dd-f-2{display:grid;grid-template-columns:auto minmax(0,1fr);gap:18px 28px}
.dd-chip{display:inline-flex;align-items:center;gap:8px;height:36px;padding:0 14px;border-radius:999px;border:1px solid var(--dd-line);background:var(--dd-card2);color:var(--dd-ink2);font:700 .84rem inherit;cursor:pointer;white-space:nowrap;transition:border-color .15s,background .15s,color .15s}
.dd-chip:hover{color:#fff;border-color:var(--dd-line2)}
.dd-chip[aria-pressed="true"]{color:#fff;border-color:var(--dd-acc);background:var(--dd-accsoft)}
.dd-chip:disabled{opacity:.42;cursor:not-allowed}
.dd-chip .n{font:600 .74rem var(--f-mono);color:var(--dd-ink3)}
.dd-chip svg.bm-flag{display:block;border-radius:3px}
.dd-chip-logo{padding:0 18px}
.dd-chip img{display:block}
.dd-sliders{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px 30px;padding-top:4px}
.dd-sl{display:flex;flex-direction:column;gap:9px;min-width:0}
.dd-sl-h{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.dd-sl-v{font-size:.82rem;font-weight:700;color:var(--dd-ink3);font-variant-numeric:tabular-nums}
.dd-sl-v.on{color:#fff}
.dd-range{position:relative;height:26px}
.dd-range .tr{position:absolute;left:0;right:0;top:11px;height:4px;border-radius:99px;background:var(--dd-card3)}
.dd-range .fi{position:absolute;top:11px;height:4px;border-radius:99px;background:var(--dd-grad)}
.dd-range input{position:absolute;inset:0;width:100%;height:26px;margin:0;background:transparent;pointer-events:none;-webkit-appearance:none;appearance:none}
.dd-range input::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;pointer-events:auto;width:18px;height:18px;border-radius:99px;background:#fff;border:2px solid var(--dd-acc);box-shadow:0 2px 6px rgba(0,0,0,.4);cursor:grab}
.dd-range input::-moz-range-thumb{pointer-events:auto;width:14px;height:14px;border-radius:99px;background:#fff;border:2px solid var(--dd-acc);cursor:grab}
.dd-range input::-webkit-slider-runnable-track{background:transparent}.dd-range input::-moz-range-track{background:transparent}
.dd-range input:focus-visible::-webkit-slider-thumb{box-shadow:0 0 0 4px var(--dd-accsoft)}
/* toolbar */
.dd-bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin:20px 0 14px}
.dd-note{margin:0;color:var(--dd-ink3);font-size:.86rem}
.dd-bar-r{display:flex;align-items:center;gap:10px}
.dd-sort select{height:38px;border-radius:11px;border:1px solid var(--dd-line2);background:var(--dd-card2);color:#fff;padding:0 12px;font-size:.86rem;font-weight:600;outline:none}
.dd-seg{display:inline-flex;padding:3px;gap:2px;border-radius:12px;background:var(--dd-card2);border:1px solid var(--dd-line)}
.dd-seg button{height:30px;padding:0 13px;border-radius:9px;border:0;background:transparent;color:var(--dd-ink3);font-weight:700;font-size:.82rem;cursor:pointer}
.dd-seg button[aria-pressed="true"]{color:#fff;background:var(--dd-card);box-shadow:0 0 0 1px var(--dd-line2) inset}
/* cards */
.dd-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:0;padding:0;list-style:none}
.dd-card2{display:flex;flex-direction:column;border-radius:20px;background:var(--dd-card);border:1px solid var(--dd-line);overflow:hidden;transition:transform .2s,border-color .2s,box-shadow .2s}
.dd-card2:hover{transform:translateY(-2px);border-color:var(--dd-line2);box-shadow:0 22px 50px -32px rgba(0,0,0,.9)}
.dd-cb{display:flex;flex-direction:column;gap:12px;padding:20px 20px 16px}
.dd-ch{display:flex;justify-content:space-between;align-items:center;gap:8px}
.dd-fam-s{font:700 .74rem inherit;color:var(--dd-ink3)}
.dd-tags{display:flex;flex-wrap:wrap;gap:6px}
.dd-tag{display:inline-flex;align-items:center;height:22px;padding:0 9px;border-radius:999px;font-size:.7rem;font-weight:800;word-spacing:.14em;border:1px solid transparent;white-space:nowrap}
