/**
 * The ONE switch for customer/public dedicated-server surfaces.
 *
 * A viewer may see them when EITHER
 *   - Setting dedicated_public_enabled is on (the public launch), OR
 *   - they are a private-preview account for "dedicated" (lib/preview-access.ts,
 *     Setting preview_access_emails; default: the owner's own customer account).
 * Everyone else gets a plain 404, exactly as if the route did not exist.
 *
 * Every customer route (app/(marketing)/dedicated-servers, app/dashboard/dedicated/**)
 * calls `requireDedicatedAccess()` first, and every customer server action calls
 * `dedicatedAccessFor(user)`. Admin previews (app/admin/preview/dedicated/**) do
 * NOT use this gate — they are admin-only and render with `preview` set.
 *
 * Indexing/sitemap/nav: the sitemap lists the page only when the PUBLIC flag is
 * on; metadata is noindex unless public; the portal nav entry is shown only to
 * viewers who pass this gate.
 *
 * test/dedicated-gate.test.ts asserts all of the above.
 */
import { notFound } from "next/navigation";
import { getSettingBool } from "../settings";
import { currentUser } from "../auth";
import { isPreviewUser } from "../preview-access";
import { DEDICATED_COUNTRY_PAGES, dedicatedCountryPath } from "./regions";

export const DEDICATED_PUBLIC_FLAG = "dedicated_public_enabled";
export const DEDICATED_PUBLIC_PATH = "/dedicated-servers";
export const DEDICATED_DASHBOARD_PATH = "/dashboard/dedicated";
export const DEDICATED_ORDER_PATH = "/dashboard/dedicated/order";

/** Pure decision (unit-tested): render, or 404. */
export function dedicatedRouteDecision(flagOn: boolean, previewUser = false): "render" | "not-found" {
  return flagOn || previewUser ? "render" : "not-found";
}

export async function dedicatedPublicEnabled(): Promise<boolean> {
  try {
    return await getSettingBool(DEDICATED_PUBLIC_FLAG, false);
  } catch {
    return false; // fail CLOSED: a DB hiccup must never expose an unreleased page
  }
}

export type DedicatedAccess = { allowed: boolean; isPublic: boolean; preview: boolean };

/** Access for an already-loaded user (server actions, layouts). Never throws. */
export async function dedicatedAccessFor(user: { email?: string | null } | null | undefined): Promise<DedicatedAccess> {
  const isPublic = await dedicatedPublicEnabled();
  const preview = !isPublic && (await isPreviewUser(user, "dedicated"));
  return { allowed: dedicatedRouteDecision(isPublic, preview) === "render", isPublic, preview };
}

/** Route guard: 404 unless the viewer may see dedicated servers. */
export async function requireDedicatedAccess(): Promise<DedicatedAccess> {
  let user = null;
  try {
    user = await currentUser();
  } catch {
    user = null;
  }
  const access = await dedicatedAccessFor(user);
  if (!access.allowed) notFound();
  return access;
}

/** Sitemap paths contributed by this feature (empty unless PUBLIC — a preview never advertises). */
export function dedicatedSitemapPaths(flagOn: boolean): string[] {
  return flagOn ? [DEDICATED_PUBLIC_PATH, ...DEDICATED_COUNTRY_PAGES.map((p) => dedicatedCountryPath(p.slug))] : [];
}

/** Every bare-metal marketing path (the main page + country pages): never in the NXM route sitemap list. */
export const DEDICATED_MARKETING_PATHS: string[] = [DEDICATED_PUBLIC_PATH, ...DEDICATED_COUNTRY_PAGES.map((p) => dedicatedCountryPath(p.slug))];
