export const NX_FAMILIES = ["NX-Core", "NX-Pulse", "NX-Forge", "NX-Titan", "NX-GPU"] as const;
export type NxFamily = (typeof NX_FAMILIES)[number];

export const NX_FAMILY_INFO: Record<NxFamily, { blurb: string; order: number; short: string }> = {
  "NX-Core": { blurb: "Proven single-tenant hardware at an entry price", order: 1, short: "Entry" },
  "NX-Pulse": { blurb: "High-clock CPUs for game servers and latency-sensitive apps", order: 2, short: "High clock" },
  "NX-Forge": { blurb: "Current-generation server CPUs for production workloads", order: 3, short: "Production" },
  "NX-Titan": { blurb: "Many-core and dual-socket platforms for virtualisation and data", order: 4, short: "Many-core" },
  "NX-GPU": { blurb: "Dedicated GPUs for AI inference, rendering and transcoding", order: 5, short: "Accelerated" },
};

export type NxNameInput = {
  /** Full CPU string, e.g. "AMD EPYC 4344P" or "2x Intel Xeon Gold 6526Y". */
  cpu: string;
  /** Sockets; 1 when unknown. */
  cpuCount?: number | null;
  /** TOTAL cores across sockets. */
  cores: number;
  ramGb: number;
  gpu?: string | null;
};

/** Earlier-generation CPUs (sold as NX-Core even when they have many cores, unless Titan-sized). */
function legacy(s: string): boolean {
  return (
    /ryzen\s*\d\s*(pro\s*)?[1-3]\d{3}/.test(s) ||               // Ryzen 1000-3000
    /\bi[3579]-?\s*[2-9]\d{3}/.test(s) ||                        // Core 2nd-9th gen (i7-7700K, i7-6700k)
    /xeon[\s-]*e3|xeon[\s-]*e5|xeon[\s-]*d[\s-]*\d|atom|celeron|opteron/.test(s) ||
    /xeon[\s-]*e[\s-]*2[12]\d{2}/.test(s)                         // Xeon-E 21xx / 22xx
  );
}

function highClockDesktop(s: string): boolean {
  if (/x3d/.test(s)) return true;
  if (/ryzen/.test(s)) return true;
  if (/core\s*ultra|\bi[579]-?\s*1\d{4}/.test(s)) return true;
  return false;
}

function serverClass(s: string): boolean {
  return /epyc|xeon[\s-]*(gold|silver|platinum|6\d{3}|w-)|xeon[\s-]*e[\s-]*2[3-9]\d{2}/.test(s);
}

export function nxFamily(i: NxNameInput): NxFamily {
  const s = (i.cpu ?? "").toLowerCase();
  if (i.gpu && i.gpu.trim()) return "NX-GPU";
  if (i.cores >= 32 || (i.cpuCount ?? 1) >= 2 || /^\s*[2-9]\s*x\s/.test(s)) return "NX-Titan";
  if (legacy(s)) return i.cores >= 12 && serverClass(s) ? "NX-Forge" : "NX-Core";
  if (highClockDesktop(s)) return "NX-Pulse";
  if (serverClass(s) || i.cores >= 12) return "NX-Forge";
  return "NX-Core";
}

