    vendors.push(vendorTile({ key: "nvidia", brand: "GPU", logo: "nvidia", h: 52, alt: "NVIDIA", lines: models.length ? `NVIDIA ${models.slice(0, 2).join(" · ")}` : "NVIDIA GPUs", list: gpus, go: "See GPU builds",
      facts: gpus.length
        ? fact("In stock", plural(gpus.length, "GPU build")) + fact("Up to", `${coresMax(gpus)} CPU cores`) + fact("From", `${usd(Math.min(...gpus.map(fromOf)))}<small>/mo</small>`)
