/* ============ Bare metal: live catalogue (data from the page loader, __NXM) ============
   Owner picks (2026-10-08): class tiles + location chips + sliders over the card grid
   (concept A), a left rail beside coloured-edge rows in the list view (concept D), and
   the shared build card (A's art well + C's glass tags, name on the art and spec icons,
   each important spec in its own mini-card). Same anatomy as the portal's catalogue. */
(function () {
  var D = (typeof __NXM !== 'undefined' && __NXM) || { cards: [], regions: [], flags: {}, families: [], tagLabel: {}, tagRule: {}, icons: {}, famTint: {}, famIcon: {} };
  var grid = document.getElementById('dd-grid');
  var main = document.getElementById('main');
  var RMQ = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return '&#' + c.charCodeAt(0) + ';'; }); };

  /* ---- reveal once on entry (fade-up 12px, staggered by --d), never re-triggered ---- */
  var io = null;
  if (!RMQ && 'IntersectionObserver' in window && main) {
    main.classList.add('dd-anim');
    io = new IntersectionObserver(function (es) {
      es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } });
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.01 });
    document.querySelectorAll('.dd-rv').forEach(function (el) { io.observe(el); });
  }
  var reveal = function (els) {
    if (!io) { els.forEach(function (el) { el.classList.add('in'); }); return; }
    els.forEach(function (el, i) { el.style.setProperty('--d', String(i % 6)); io.observe(el); });
  };

  /* vendor tiles in the hardware showcase jump to the filtered catalogue */
  var goBrand = null;
  document.querySelectorAll('.dd-v-go[data-brand]').forEach(function (b) {
    b.addEventListener('click', function () { if (goBrand) goBrand(b.getAttribute('data-brand')); });
  });

  if (!grid) return;
  var cat = document.getElementById('catalogue');

  var icon = function (n, s) {
    var d = D.icons && D.icons[n]; if (!d) return '';
    return '<svg viewBox="0 0 24 24" width="' + (s || 16) + '" height="' + (s || 16) + '" aria-hidden="true" ' +
      (d.fill ? 'fill="currentColor"' : 'fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"') + '><path d="' + d.d + '"/></svg>';
  };
  var LOGO = { amd: '/nxm/home/logos-amd.svg', intel: '/nxm/home/logos-intel.svg', nvidia: '/nxm/home/logos-nvidia.svg' };
  var logo = function (b, h) { return b && LOGO[b] ? '<img src="' + LOGO[b] + '" alt="' + (b === 'amd' ? 'AMD' : b === 'intel' ? 'Intel' : 'NVIDIA') + '" style="height:' + (h || 13) + 'px !important;width:auto !important">' : ''; };
  var flag = function (c) { return (D.flags && D.flags[c]) || ''; };
  /* tag colours + marks: the portal's (components/dedicated/bm.css .bm-tag-*) */
  var TAG = { popular: ['#f2b84b', 'star'], recommended: ['#b9a8ff', 'certbadge'], value: ['#2fd39a', 'tag'], performance: ['#5fd0ff', 'bolt'], gpu: ['#a3e635', 'bmgpu'], 'new': ['#ff7ad9', 'sparkles'] };
  var STEPS = {
    price: { label: 'Monthly price', s: [0, 50, 100, 150, 200, 300, 500, 750, 1000, 1500, 2500, 5000], f: function (n) { return __nxmMoney(n).replace(/\.00(?=\D*$)/, ''); } },
    cores: { label: 'CPU cores', s: [0, 4, 6, 8, 12, 16, 24, 32, 48, 64, 96, 128, 192], f: function (n) { return String(n); } },
    ram: { label: 'Memory', s: [0, 16, 32, 64, 96, 128, 192, 256, 384, 512, 768], f: function (n) { return n + ' GB'; } },
    disk: { label: 'Storage', s: [0, 500, 1000, 2000, 4000, 8000, 16000, 32000, 64000], f: function (n) { return n >= 1000 ? (n / 1000) + ' TB' : n + ' GB'; } }
  };
  var preCountry = D.preCountry || null;
  var initRegions = function () { return preCountry ? (D.regions || []).filter(function (r) { return r.country === preCountry && r.inStock; }).map(function (r) { return r.code; }) : []; };
  var st = { regions: initRegions(), brands: [], fam: '', q: '', sort: 'price', view: 'cards', limit: 12, r: {} };
  Object.keys(STEPS).forEach(function (k) { st.r[k] = [0, STEPS[k].s.length - 1]; });
  try { var v = localStorage.getItem('bm-view'); if (v === 'list' || v === 'cards') st.view = v; } catch (e) {}

  /* class tiles (concept A): All builds + one tile per class, live counts */
  var clsBox = document.getElementById('dd-classes');
  clsBox.innerHTML = '<button type="button" class="dd-cls" data-fam="" aria-pressed="true"><span class="dd-cls-ic">' + icon('layers', 18) + '</span><span class="dd-cls-t">All builds</span><span class="dd-cnt" data-n=""></span></button>' +
    (D.families || []).map(function (f) {
      return '<button type="button" class="dd-cls" data-fam="' + esc(f) + '" aria-pressed="false" style="--tint:' + esc((D.famTint || {})[f] || '#8b6cff') + '"><span class="dd-cls-ic">' + icon((D.famIcon || {})[f] || 'bmchip', 18) + '</span><span class="dd-cls-t">' + esc(f) + '</span><span class="dd-cnt" data-n="' + esc(f) + '"></span></button>';
    }).join('');
  clsBox.addEventListener('click', function (e) {
    var b = e.target.closest('[data-fam]'); if (!b || b.disabled) return;
    st.fam = b.getAttribute('data-fam'); sync(); render(true);
  });
  document.querySelectorAll('.dd-fam-go[data-family]').forEach(function (b) {
    b.addEventListener('click', function () {
      st.fam = b.getAttribute('data-family'); sync(); render(true);
      if (cat) cat.scrollIntoView({ behavior: RMQ ? 'auto' : 'smooth', block: 'start' });
    });
  });

  /* locations: chips with flags in the card view, checkbox rows in the list view's rail */
  var locBox = document.getElementById('dd-locs-f');
  var locHtml = '<button type="button" class="dd-loc-o dd-loc-all" data-loc="all" aria-pressed="' + (st.regions.length ? 'false' : 'true') + '"><span class="cb" aria-hidden="true"></span><span class="fl">' + icon('globe', 15) + '</span><span class="t">All locations</span></button>';
  (D.regions || []).forEach(function (r) {
    locHtml += '<button type="button" class="dd-loc-o" data-loc="' + esc(r.code) + '" aria-pressed="' + (st.regions.indexOf(r.code) >= 0) + '"' + (r.inStock ? '' : ' disabled') + ' title="' + (r.inStock ? r.inStock + ' builds in stock' : 'Sold out right now') + '"><span class="cb" aria-hidden="true"></span><span class="fl">' + flag(r.country) + '</span><span class="t">' + esc(r.label) + '</span><span class="n">' + (r.inStock || 0) + '</span></button>';
  });
  locBox.innerHTML = locHtml;
  locBox.addEventListener('click', function (e) {
    var b = e.target.closest('[data-loc]'); if (!b || b.disabled) return;
    var code = b.getAttribute('data-loc');
    if (code === 'all') st.regions = [];
    else { var i = st.regions.indexOf(code); if (i >= 0) st.regions.splice(i, 1); else st.regions.push(code); }
    sync(); render(true);
  });

  /* processor logos */
  var anyGpu = (D.cards || []).some(function (c) { return c.gpu; });
  document.querySelectorAll('#dd-brands [data-brand]').forEach(function (b) {
    if (b.getAttribute('data-brand') === 'GPU' && !anyGpu) b.hidden = true;
    b.addEventListener('click', function () {
      var k = b.getAttribute('data-brand'), i = st.brands.indexOf(k);
      if (i >= 0) st.brands.splice(i, 1); else st.brands.push(k);
      sync(); render(true);
    });
  });
  goBrand = function (k) {
    st.brands = [k]; st.fam = ''; sync(); render(true);
    if (cat) cat.scrollIntoView({ behavior: RMQ ? 'auto' : 'smooth', block: 'start' });
  };

  /* sliders (two stacked native ranges per filter: keyboard + screen-reader friendly) */
  var sl = document.getElementById('dd-sliders');
  sl.innerHTML = Object.keys(STEPS).map(function (k) {
    var S = STEPS[k], max = S.s.length - 1;
    return '<div class="dd-sl" data-k="' + k + '"><div class="dd-sl-h"><span class="dd-k" id="dd-sl-' + k + '">' + S.label + '</span><span class="dd-sl-v">Any</span></div>' +
      '<div class="dd-range"><span class="tr"></span><span class="fi"></span>' +
      '<input type="range" min="0" max="' + max + '" step="1" value="0" aria-label="' + S.label + ' minimum">' +
      '<input type="range" min="0" max="' + max + '" step="1" value="' + max + '" aria-label="' + S.label + ' maximum"></div></div>';
  }).join('');
  sl.querySelectorAll('.dd-sl').forEach(function (box) {
    var k = box.getAttribute('data-k'), ins = box.querySelectorAll('input');
    ins[0].addEventListener('input', function () { st.r[k] = [Math.min(+ins[0].value, st.r[k][1]), st.r[k][1]]; sync(); render(true); });
    ins[1].addEventListener('input', function () { st.r[k] = [st.r[k][0], Math.max(+ins[1].value, st.r[k][0])]; sync(); render(true); });
  });

  /* search, sort, view, reset, more, the phone filter toggle */
  var q = document.getElementById('dd-q');
  q.addEventListener('input', function () { st.q = q.value.trim().toLowerCase(); sync(); render(true); });
  document.getElementById('dd-sort').addEventListener('change', function (e) { st.sort = e.target.value; render(true); });
  document.querySelectorAll('.dd-seg [data-view]').forEach(function (b) {
    b.addEventListener('click', function () { st.view = b.getAttribute('data-view'); try { localStorage.setItem('bm-view', st.view); } catch (e) {} sync(); render(false); });
  });
  var panel = document.getElementById('dd-filter'), ft = document.getElementById('dd-ftoggle');
  ft.addEventListener('click', function () { var on = !panel.classList.contains('open'); panel.classList.toggle('open', on); ft.setAttribute('aria-expanded', String(on)); });
  var reset = function () {
    st.regions = []; st.brands = []; st.fam = ''; st.q = ''; q.value = '';
    Object.keys(STEPS).forEach(function (k) { st.r[k] = [0, STEPS[k].s.length - 1]; });
    sync(); render(true);
  };
  document.getElementById('dd-reset').addEventListener('click', reset);
  document.getElementById('dd-empty-reset').addEventListener('click', reset);
  var more = document.getElementById('dd-more');
  more.addEventListener('click', function () { st.limit += 12; render(false, true); });

  function within(v, k) { var S = STEPS[k].s, r = st.r[k]; return v >= S[r[0]] && (r[1] === S.length - 1 || v <= S[r[1]]); }
  function active() {
    var n = st.regions.length + st.brands.length + (st.fam ? 1 : 0) + (st.q ? 1 : 0);
    Object.keys(STEPS).forEach(function (k) { if (st.r[k][0] > 0 || st.r[k][1] < STEPS[k].s.length - 1) n++; });
    return n;
  }
  function sync() {
    locBox.querySelectorAll('[data-loc]').forEach(function (b) { var c = b.getAttribute('data-loc'); b.setAttribute('aria-pressed', c === 'all' ? String(st.regions.length === 0) : String(st.regions.indexOf(c) >= 0)); });
    document.querySelectorAll('#dd-brands [data-brand]').forEach(function (b) { b.setAttribute('aria-pressed', String(st.brands.indexOf(b.getAttribute('data-brand')) >= 0)); });
    clsBox.querySelectorAll('[data-fam]').forEach(function (b) { b.setAttribute('aria-pressed', String(b.getAttribute('data-fam') === st.fam)); });
    sl.querySelectorAll('.dd-sl').forEach(function (box) {
      var k = box.getAttribute('data-k'), S = STEPS[k], max = S.s.length - 1, r = st.r[k], ins = box.querySelectorAll('input');
      ins[0].value = r[0]; ins[1].value = r[1];
      var fmt = function (i, edge) { return edge === 'max' && i === max ? S.f(S.s[i]) + '+' : S.f(S.s[i]); };
      ins[0].setAttribute('aria-valuetext', fmt(r[0], 'min')); ins[1].setAttribute('aria-valuetext', fmt(r[1], 'max'));
      var v = box.querySelector('.dd-sl-v'), any = r[0] === 0 && r[1] === max;
      v.textContent = any ? 'Any' : fmt(r[0], 'min') + ' – ' + fmt(r[1], 'max'); v.classList.toggle('on', !any);
      var fi = box.querySelector('.fi'); fi.style.left = (r[0] / max * 100) + '%'; fi.style.width = ((r[1] - r[0]) / max * 100) + '%';
    });
    document.querySelectorAll('.dd-seg [data-view]').forEach(function (b) { b.setAttribute('aria-pressed', String(b.getAttribute('data-view') === st.view)); });
    if (cat) cat.setAttribute('data-view', st.view);
    var n = active(), rb = document.getElementById('dd-reset');
    rb.disabled = n === 0; rb.textContent = n ? 'Reset (' + n + ')' : 'Reset';
    document.getElementById('dd-fcount').textContent = n ? String(n) : '';
  }

  var unit = function (c) { return Math.max(1, c.cores) + c.ramGb / 8; };
  var tagPills = function (c, max) {
    return (c.tags || []).slice(0, max || 3).map(function (t) {
      var m = TAG[t] || ['#b9a8ff', 'tag'];
      return '<span class="dd-tag" style="--t:' + m[0] + '" title="' + esc(D.tagRule[t] || '') + '">' + icon(m[1], 12) + esc(D.tagLabel[t] || t) + '</span>';
    }).join('');
  };
  var flagsOf = function (regs, max) {
    var seen = {}, out = [];
    regs.forEach(function (r) { if (!seen[r.country]) { seen[r.country] = 1; out.push(r.country); } });
    var lim = max || 5;
    return '<span class="dd-flags" title="' + esc(regs.map(function (r) { return r.label; }).join(', ')) + '"><span class="sr-only">' + esc(regs.map(function (r) { return r.label; }).join(', ')) + '</span>' + out.slice(0, lim).map(flag).join('') + (out.length > lim ? '<em>+' + (out.length - lim) + '</em>' : '') + '</span>';
  };
  var hrefOf = function (c, regs) { return st.regions.length === 1 ? c.hrefTpl.replace('__REGION__', encodeURIComponent(regs[0].region)) : c.href; };
  var times = function (s) { return String(s || '').replace(/(\d+)\s*x\s+/gi, '$1× '); };
  var mini = function (ic, k, v, sub, cls) {
    return '<div class="dd-mini' + (cls ? ' ' + cls : '') + '"><span class="dd-mini-ic">' + ic + '</span><span class="dd-mini-t"><small>' + k + '</small><b>' + v + '</b>' + (sub ? '<em>' + sub + '</em>' : '') + '</span></div>';
  };

  function card(c, regs, from) {
    return '<li class="dd-bcard" style="--tint:' + esc(c.tint || '#8b6cff') + '">' +
      '<div class="dd-well"><img class="dd-well-plate" src="/nx/plates/aurora-veil.webp" alt="" aria-hidden="true" loading="lazy" decoding="async"><span class="dd-well-glow"></span>' +
      '<img class="dd-well-art" src="' + esc(c.art) + '" alt="" aria-hidden="true" width="711" height="711" loading="lazy" decoding="async"><span class="dd-well-fade"></span>' +
      ((c.tags || []).length ? '<div class="dd-tags">' + tagPills(c) + '</div>' : '') +
      '<div class="dd-id"><span class="dd-fam-k">' + esc(c.family) + ' · ' + esc(c.familyShort) + '</span><h3 class="dd-name">' + esc(c.name) + '</h3>' +
      '<p class="dd-cpu">' + logo(c.cpuBrand, 12) + '<span>' + esc(times(c.cpuShort)) + '</span></p></div></div>' +
      '<div class="dd-specs">' +
      mini(icon('bmchip', 18), 'Cores', esc(c.cores) + ' cores · ' + esc(c.threads) + ' threads', c.ghz ? 'up to ' + esc(c.ghz) + ' GHz' : '') +
      mini(icon('ram', 18), 'Memory', esc(c.ramGb) + ' GB', c.maxRamGb > c.ramGb ? 'up to ' + esc(c.maxRamGb) + ' GB' : 'dedicated to you') +
      mini(icon('database', 18), 'Storage', esc(times(c.storage) || '—'), c.raid ? esc(c.raid) : 'your own disks') +
      mini(icon('nodes', 18), 'Network', esc(c.bandwidth || '—'), 'DDoS protection included') +
      (c.gpu ? mini(logo(c.gpuBrand || 'nvidia', 13) || icon('bmgpu', 18), 'GPU', esc(c.gpu), 'dedicated to this server', 'dd-mini-wide') : '') +
      '</div><div class="dd-cf">' + flagsOf(regs) + '<div class="dd-pr"><small>from</small><b>' + __nxmMoney(from) + '</b><em>/mo</em></div>' +
      '<a class="dd-go" href="' + esc(hrefOf(c, regs)) + '" aria-label="Configure ' + esc(c.name) + '">Configure <span aria-hidden="true">→</span></a></div></li>';
  }
  function row(c, regs, from) {
    return '<li class="dd-row" style="--tint:' + esc(c.tint || '#8b6cff') + '"><span class="dd-edge" aria-hidden="true"></span>' +
      '<span class="dd-thumb" aria-hidden="true"><img src="' + esc(c.art) + '" alt="" width="711" height="711" loading="lazy" decoding="async"></span>' +
      '<div class="nm"><b>' + esc(c.name) + '</b>' + ((c.tags || []).length ? '<span class="dd-tagrow">' + tagPills(c, 2) + '</span>' : '') +
      '<span class="cpu">' + logo(c.cpuBrand, 11) + esc(times(c.cpuShort)) + (c.gpu ? ' · ' + esc(c.gpu) : '') + '</span></div>' +
      '<div class="c"><b>' + esc(c.cores) + 'C/' + esc(c.threads) + 'T</b><span>' + esc(c.ramGb) + ' GB · ' + esc(times(c.storage)) + '</span></div>' + flagsOf(regs, 4) +
      '<div class="end"><span class="p"><b>' + __nxmMoney(from) + '</b><small>/mo</small></span><a class="dd-go" href="' + esc(hrefOf(c, regs)) + '" aria-label="Configure ' + esc(c.name) + '">Configure</a></div></li>';
  }

  var first = true;
  function render(resetLimit, grow) {
    if (resetLimit) st.limit = 12;
    var rows = [], famCount = {}, all = 0;
    (D.cards || []).forEach(function (c) {
      var regs = (c.regions || []).filter(function (r) { return r.inStock && (st.regions.length === 0 || st.regions.indexOf(r.code) >= 0); });
      if (!regs.length) return;
      var from = Math.min.apply(null, regs.map(function (r) { return r.from; }));
      if (st.brands.length && !st.brands.some(function (b) { return b === 'GPU' ? !!c.gpu : c.cpuBrandName === b; })) return;
      if (!within(from, 'price') || !within(c.cores, 'cores') || !(within(c.ramGb, 'ram') || within(c.maxRamGb, 'ram')) || !within(c.storageGb, 'disk')) return;
      if (st.q && (c.name + ' ' + c.cpuShort + ' ' + (c.gpu || '') + ' ' + c.storage).toLowerCase().indexOf(st.q) < 0) return;
      famCount[c.family] = (famCount[c.family] || 0) + 1; all++;
      if (st.fam && c.family !== st.fam) return;
      rows.push({ c: c, regs: regs, from: from });
    });
    clsBox.querySelectorAll('.dd-cnt').forEach(function (el) { var k = el.getAttribute('data-n'); el.textContent = String(k ? famCount[k] || 0 : all); });
    rows.sort(function (a, b) {
      return st.sort === 'price' ? a.from - b.from : st.sort === 'price-desc' ? b.from - a.from
        : st.sort === 'value' ? a.from / unit(a.c) - b.from / unit(b.c)
        : st.sort === 'cores' ? b.c.cores - a.c.cores || a.from - b.from
        : st.sort === 'ram' ? b.c.maxRamGb - a.c.maxRamGb || a.from - b.from
        : b.c.storageGb - a.c.storageGb || a.from - b.from;
    });
    document.getElementById('dd-count').innerHTML = '<b>' + rows.length + '</b> of ' + (D.cards || []).length + ' in-stock builds match';
    var before = grow ? grid.children.length : 0;
    grid.className = 'dd-grid' + (st.view === 'list' ? ' list' : '');
    grid.innerHTML = rows.slice(0, st.limit).map(function (x) { return st.view === 'list' ? row(x.c, x.regs, x.from) : card(x.c, x.regs, x.from); }).join('');
    var items = Array.prototype.slice.call(grid.children);
    // first paint and "Show more" reveal (staggered); a filter change swaps in place
    if (first || grow) { items.slice(before).forEach(function (el) { el.classList.add('dd-rv'); }); reveal(items.slice(before)); }
    first = false;
    more.hidden = rows.length <= st.limit;
    document.getElementById('dd-empty').hidden = rows.length > 0;
    grid.hidden = rows.length === 0;
  }
  sync(); render(true);
})();

