head='''/* ================= Bare Metal Dedicated Servers (native page) =================
   Owner-approved v2 (2026-10-08): concept B's quiet centred hero with the three size
   renders, an infrastructure showcase of the real chip makers, concept A's filter over
   the shared build card (A's art well + C's glass tags, name on art and spec icons, one
   mini-card per spec), concept D's rail + coloured-edge rows for the list view. The
   card anatomy matches the portal's (components/dedicated/bm.css .bm-bcard/.bm-well/.bm-spec).
   Neutral surfaces; violet->blue only for actions, selected state and glows. */
main{overflow:clip}
.pg-dd{--dd-card:#0e131b;--dd-card2:#141a24;--dd-card3:#1a212d;--dd-line:rgba(255,255,255,.075);--dd-line2:rgba(255,255,255,.14);--dd-ink:#f3f5f9;--dd-ink2:#b9c1ce;--dd-ink3:#8a93a3;--dd-acc:#8b6cff;--dd-acc2:#4f7dff;--dd-accink:#b9a8ff;--dd-accsoft:rgba(139,108,255,.14);--dd-ok:#2fd39a;--dd-warn:#f2b84b;--dd-grad:linear-gradient(100deg,#8b6cff,#4f7dff);--dd-rim:#002a5e;--dd-glass:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.015))}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.dd-eyebrow{display:block;margin-bottom:14px;font:600 .76rem var(--f-mono);letter-spacing:.16em;text-transform:uppercase;color:var(--dd-accink)}

/* ---------- motion: reveal once (fade-up 12px), off under reduced motion ---------- */
@keyframes dd-up{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
@keyframes dd-rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@keyframes dd-drift{from{transform:translateX(-51.5%) scale(1.04)}to{transform:translateX(-48.5%) scale(1.04)}}
.dd-anim .dd-rv:not(.in){opacity:0}
.dd-anim .dd-rv.in{animation:dd-up .6s cubic-bezier(.2,.7,.2,1) calc(var(--d,0) * 50ms) backwards}

/* ---------- hero (concept B) ---------- */
.dd-hero{position:relative;padding:calc(var(--nav-h) + clamp(56px,7vw,92px)) 0 clamp(48px,6vw,80px);isolation:isolate;text-align:center}
.dd-sky{position:absolute;inset:0;z-index:-1;overflow:hidden;pointer-events:none}
.dd-plate{position:absolute;left:50%;top:calc(var(--nav-h) - 48px);width:max(1500px,125%);max-width:none;height:auto;opacity:.5;transform:translateX(-50%) scale(1.04);-webkit-mask-image:linear-gradient(180deg,#000 0%,#000 46%,transparent 78%);mask-image:linear-gradient(180deg,#000 0%,#000 46%,transparent 78%)}
.dd-sky-fade{position:absolute;inset:auto 0 0;height:220px;background:linear-gradient(180deg,transparent,var(--bg))}
.dd-hero-in{display:flex;flex-direction:column;align-items:center}
.dd-hero h1{margin:0 0 22px;font-weight:700}
.dd-kicker{display:block;margin:0 0 18px;font:600 .78rem var(--f-mono);letter-spacing:.16em;text-transform:uppercase;color:#3EDCF2}
.dd-h{display:block;max-width:17ch;margin-inline:auto;font-size:clamp(2.5rem,5.6vw,4.7rem);line-height:1.02;letter-spacing:-.04em;font-weight:700;color:#fff;text-wrap:balance}
.dd-h span{color:rgba(255,255,255,.55)}
.dd-lede{margin:0 auto 30px;max-width:58ch;color:rgba(255,255,255,.68);font-size:clamp(1.02rem,1.25vw,1.14rem);line-height:1.65}
.dd-ctas{justify-content:center}
.dd-lineup{position:relative;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:end;gap:clamp(14px,3.4vw,44px);width:100%;max-width:660px;margin:44px auto 0;padding:0;list-style:none}
.dd-lineup::after{content:"";position:absolute;left:4%;right:4%;bottom:26px;height:56px;z-index:-1;background:radial-gradient(50% 50% at 50% 50%,rgba(123,63,239,.32),transparent 72%);filter:blur(6px)}
.dd-lineup li{display:flex;flex-direction:column;align-items:center;gap:10px;min-width:0}
.dd-size{display:block;width:100%;aspect-ratio:1;transition:transform .45s cubic-bezier(.2,.7,.2,1)}
.dd-size img{display:block;width:100%;height:100%;object-fit:contain;object-position:bottom;filter:drop-shadow(0 18px 30px rgba(60,40,200,.35));transition:filter .45s ease}
.dd-lineup li:hover .dd-size{transform:translateY(-6px)}
.dd-lineup li:hover .dd-size img{filter:drop-shadow(0 22px 36px rgba(110,80,255,.6))}
.dd-lineup small{font:600 .68rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--dd-ink3);white-space:nowrap}
.dd-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));width:100%;max-width:760px;margin:34px auto 0;padding-top:22px;border-top:1px solid var(--dd-line)}
.dd-stats>div{padding:0 12px}
.dd-stats>div+div{border-left:1px solid var(--dd-line)}
.dd-stats dt{font:600 .64rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--dd-ink3)}
.dd-stats dd{margin:6px 0 0;font-size:clamp(1.2rem,1.8vw,1.5rem);font-weight:800;letter-spacing:-.03em;color:#fff;font-variant-numeric:tabular-nums}
.dd-stats dd small{font-size:.78rem;font-weight:600;color:var(--dd-ink2);letter-spacing:0}
@media (prefers-reduced-motion:no-preference){
  .dd-plate{animation:dd-drift 64s ease-in-out infinite alternate}
  .dd-lineup li{animation:dd-rise .9s cubic-bezier(.2,.7,.2,1) calc(180ms + var(--i,0) * 140ms) backwards}
}

/* sections */
.dd-sec{padding-block:clamp(64px,8vw,110px)}
.dd-tone{background:linear-gradient(180deg,transparent,rgba(14,19,30,.6) 16%,rgba(14,19,30,.6) 84%,transparent)}
.dd-head{margin-bottom:24px}
.dd-center{text-align:center;justify-content:center}.dd-center .lede{margin-inline:auto}

/* ---------- infrastructure showcase ---------- */
.dd-infra{padding-top:clamp(28px,4vw,56px)}
.dd-vendors{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:22px;margin:30px 0 0;padding:0;list-style:none}
.dd-vendor{position:relative;display:flex;flex-direction:column;gap:14px;padding:30px 28px 24px;border-radius:22px;overflow:hidden;isolation:isolate;background:var(--dd-glass);border:1px solid rgba(255,255,255,.09);box-shadow:inset 0 1px 0 rgba(255,255,255,.06),0 24px 60px -40px rgba(0,0,0,.9);transition:border-color .3s ease}
.dd-vendor::before{content:"";position:absolute;inset:0;z-index:-1;background:radial-gradient(80% 60% at 18% 0%,color-mix(in srgb,var(--vc) 20%,transparent),transparent 70%);opacity:.8;transition:opacity .4s ease}
.dd-vendor:hover{border-color:rgba(255,255,255,.16)}.dd-vendor:hover::before{opacity:1}
.dd-v-amd{--vc:#ff5a3c}.dd-v-intel{--vc:#3b9bff}.dd-v-nvidia{--vc:#76b900}
.dd-v-mark{display:flex;align-items:center;height:72px}
.dd-v-mark img{display:block;filter:drop-shadow(0 4px 18px rgba(0,0,0,.5))}
.dd-v-lines{margin:0;font:600 .72rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--dd-ink2)}
.dd-v-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:4px 0 0;padding:16px 0;border-block:1px solid var(--dd-line)}
.dd-v-facts dt{font:600 .62rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--dd-ink3)}
.dd-v-facts dd{margin:5px 0 0;font-size:1.08rem;font-weight:800;letter-spacing:-.02em;color:#fff;font-variant-numeric:tabular-nums}
.dd-v-facts dd small{font-size:.75rem;font-weight:600;color:var(--dd-ink3)}
.dd-v-fams{display:flex;flex-wrap:wrap;gap:6px;margin:0}
.dd-v-fams span{display:inline-flex;align-items:center;gap:6px;height:24px;padding:0 10px;border-radius:999px;background:rgba(255,255,255,.04);border:1px solid var(--dd-line);color:var(--dd-ink2);font-size:.74rem;font-weight:700}
.dd-v-fams span::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--tint);box-shadow:0 0 8px var(--tint)}
.dd-v-go{align-self:flex-start;margin-top:auto;padding:0;border:0;background:none;color:var(--dd-accink);font-weight:700;font-size:.88rem;cursor:pointer}
.dd-v-go:hover{color:#fff}.dd-v-go span{display:inline-block;transition:transform .25s ease}.dd-v-go:hover span{transform:translateX(3px)}

/* ---------- catalogue: class tiles (concept A) ---------- */
.dd-classes{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:14px}
.dd-cls{display:flex;align-items:center;gap:10px;height:52px;padding:0 14px;border-radius:14px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.025);color:var(--dd-ink2);font:600 .88rem inherit;cursor:pointer;text-align:left;transition:border-color .2s,background .2s,color .2s}
.dd-cls:hover{border-color:rgba(139,108,255,.4);color:#fff}
.dd-cls[aria-pressed="true"]{border-color:rgba(139,108,255,.75);background:linear-gradient(180deg,rgba(60,40,140,.32),rgba(20,14,60,.4));color:#fff;box-shadow:inset 0 0 0 1px rgba(139,108,255,.25)}
.dd-cls:focus-visible,.dd-loc-o:focus-visible,.dd-brand:focus-visible,.dd-go:focus-visible,.dd-seg button:focus-visible,.dd-v-go:focus-visible,.dd-ftoggle:focus-visible{outline:2px solid var(--dd-acc);outline-offset:2px}
.dd-cls-ic{display:grid;place-items:center;flex:none;color:var(--tint,#fff)}
.dd-cls-t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dd-cnt{display:inline-grid;place-items:center;min-width:24px;height:21px;padding:0 7px;border-radius:7px;background:rgba(255,255,255,.07);font-size:.7rem;font-weight:800;color:var(--dd-ink2);font-variant-numeric:tabular-nums}
.dd-cls[aria-pressed="true"] .dd-cnt{background:#7b4dff;color:#fff}

/* ---------- filter panel (cards view) / rail (list view) ---------- */
.dd-layout{display:grid;gap:18px;align-items:start}
.dd-filter{display:grid;gap:16px;padding:18px 20px 20px;border-radius:20px;background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.08);box-shadow:inset 0 1px 0 rgba(255,255,255,.04)}
.dd-f-head{display:flex;align-items:center;justify-content:space-between;gap:12px}
.dd-f-head b{font-size:.95rem;color:#fff}
.dd-reset{height:32px;padding:0 12px;border-radius:10px;border:1px solid var(--dd-line2);background:transparent;color:#fff;font-weight:700;font-size:.8rem;cursor:pointer}
.dd-reset:disabled{opacity:.4;cursor:default}
.dd-f-block{display:flex;flex-direction:column;gap:10px;min-width:0}
.dd-k{font:600 .66rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--dd-ink3)}
.dd-locs-f{display:flex;flex-wrap:wrap;gap:8px}
.dd-loc-o{display:inline-flex;align-items:center;gap:8px;height:36px;padding:0 12px 0 9px;border-radius:10px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.02);color:var(--dd-ink2);font:600 .82rem inherit;white-space:nowrap;cursor:pointer;transition:border-color .15s,background .15s,color .15s}
.dd-loc-o:hover{color:#fff;border-color:var(--dd-line2)}
.dd-loc-o[aria-pressed="true"]{color:#fff;border-color:rgba(139,108,255,.7);background:rgba(139,108,255,.14)}
.dd-loc-o:disabled{opacity:.4;cursor:not-allowed}
.dd-loc-o .fl{display:grid;place-items:center;color:var(--dd-ink2)}
.dd-loc-o .fl svg{display:block;border-radius:3px}
.dd-loc-o .n{font:600 .7rem var(--f-mono);color:var(--dd-ink3)}
.dd-loc-o .cb{display:none}
.dd-f-row2{display:grid;grid-template-columns:auto minmax(0,1fr);gap:18px 32px;align-items:end}
.dd-brands{display:flex;flex-wrap:wrap;gap:8px}
.dd-brand{display:inline-flex;align-items:center;gap:7px;height:40px;padding:0 16px;border-radius:12px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.02);color:var(--dd-ink2);font:700 .78rem inherit;cursor:pointer;transition:border-color .15s,background .15s}
.dd-brand img{display:block;opacity:.85}
.dd-brand:hover{border-color:var(--dd-line2)}.dd-brand:hover img{opacity:1}
.dd-brand[aria-pressed="true"]{border-color:rgba(139,108,255,.7);background:rgba(139,108,255,.14);color:#fff}.dd-brand[aria-pressed="true"] img{opacity:1}
.dd-sliders{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px 28px}
.dd-sl{display:flex;flex-direction:column;gap:8px;min-width:0}
.dd-sl-h{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.dd-sl-v{font-size:.8rem;font-weight:700;color:var(--dd-ink3);font-variant-numeric:tabular-nums}
.dd-sl-v.on{color:#fff}
.dd-range{position:relative;height:26px}
.dd-range .tr{position:absolute;left:0;right:0;top:11px;height:4px;border-radius:99px;background:rgba(255,255,255,.08)}
.dd-range .fi{position:absolute;top:11px;height:4px;border-radius:99px;background:linear-gradient(90deg,#7b4dff,#6f7bff)}
.dd-range input{position:absolute;inset:0;width:100%;height:26px;margin:0;background:transparent;pointer-events:none;-webkit-appearance:none;appearance:none}
.dd-range input::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;pointer-events:auto;width:18px;height:18px;border-radius:99px;background:#fff;border:2px solid #7b4dff;box-shadow:0 2px 6px rgba(0,0,0,.4);cursor:grab}
.dd-range input::-moz-range-thumb{pointer-events:auto;width:14px;height:14px;border-radius:99px;background:#fff;border:2px solid #7b4dff;cursor:grab}
.dd-range input::-webkit-slider-runnable-track{background:transparent}.dd-range input::-moz-range-track{background:transparent}
.dd-range input:focus-visible::-webkit-slider-thumb{box-shadow:0 0 0 4px var(--dd-accsoft)}
/* toolbar */
.dd-results{min-width:0}
.dd-bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin:0 0 16px}
.dd-count{margin:0;color:var(--dd-ink3);font-size:.88rem}.dd-count b{color:#fff}
.dd-bar-r{display:flex;flex-wrap:wrap;align-items:center;gap:10px}
.dd-search input{height:38px;width:min(260px,60vw);border-radius:11px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.03);color:#fff;padding:0 13px;font-size:.88rem;outline:none}
.dd-search input:focus{border-color:var(--dd-acc);box-shadow:0 0 0 3px var(--dd-accsoft)}
.dd-sort select{height:38px;border-radius:11px;border:1px solid rgba(255,255,255,.1);background:#0d121b;color:#fff;padding:0 12px;font-size:.86rem;font-weight:600;outline:none}
.dd-seg{display:inline-flex;padding:3px;gap:2px;border-radius:12px;border:1px solid rgba(255,255,255,.09);background:rgba(0,0,0,.25)}
