.dd-seg button[aria-pressed="true"]{color:#fff;background:rgba(255,255,255,.09);box-shadow:inset 0 1px 0 rgba(255,255,255,.08)}
.dd-ftoggle{display:none;align-items:center;gap:8px;height:38px;padding:0 14px;border-radius:11px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.03);color:#fff;font-weight:700;font-size:.86rem;cursor:pointer}
.dd-ftoggle .n:not(:empty){display:inline-grid;place-items:center;min-width:20px;height:20px;padding:0 6px;border-radius:7px;background:#7b4dff;font-size:.7rem}
.dd-ftoggle-ic{width:14px;height:10px;border-block:2px solid currentColor;position:relative}.dd-ftoggle-ic::after{content:"";position:absolute;left:3px;right:3px;top:2px;height:2px;background:currentColor}
.dd-note{margin:18px 0 0;color:var(--dd-ink3);font-size:.84rem;text-align:center}

/* ---------- build card (shared spec with the portal) ---------- */
