.dd-bcard{display:flex;flex-direction:column;min-width:0;border-radius:17px;border:1px solid var(--dd-rim);background:linear-gradient(180deg,rgba(10,22,48,.55),rgba(2,7,20,.72));padding:5px;box-shadow:0 1px 0 rgba(255,255,255,.04) inset,0 18px 40px -24px rgba(0,0,0,.8);transition:border-color .3s ease,box-shadow .3s ease,transform .3s ease}
.dd-bcard:hover{border-color:rgba(72,148,255,.45);box-shadow:0 0 0 1px rgba(72,148,255,.12),0 18px 44px -24px rgba(72,148,255,.5);transform:translateY(-2px)}
.dd-well{position:relative;height:204px;overflow:hidden;border-radius:13px;background:#050d20;isolation:isolate}
.dd-well-plate{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.6}
