}
@media (prefers-reduced-motion:reduce){.dd-bcard,.dd-well-art,.dd-size,.dd-size img,.dd-go,.dd-vendor,.dd-row{transition:none!important}.dd-bcard:hover,.dd-go:hover,.dd-lineup li:hover .dd-size{transform:none}.dd-bcard:hover .dd-well-art{transform:none}}
