cat > /tank/dev-worktrees/bm-v2-mkt/.bmv2/shoot.mjs <<'EOF'
// node-2 only. Screens the gated page against the throwaway DB's fake catalogue.
import { chromium } from "playwright";
import fs from "node:fs";
const BASE = process.env.BASE || "http://127.0.0.1:4212";
const URL = BASE + (process.env.ROUTE || "/nxm/dedicated-servers");
const OUT = ".bmv2/out"; fs.mkdirSync(OUT, { recursive: true });
const b = await chromium.launch({ args: ["--disable-dev-shm-usage"] });
const hide = "[aria-label*=chat i],[class*=chat-launcher],[id*=chat-widget],.cookie-banner{display:none!important}";
async function settle(p) {
  await p.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 500) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 90)); } window.scrollTo(0, 0); });
  await p.waitForTimeout(1200);
}
async function clipOf(p, sels, maxH) {
  const boxes = []; for (const s of sels) { const bb = await p.locator(s).first().boundingBox(); if (bb) boxes.push(bb); }
  const x = Math.min(...boxes.map((b) => b.x)), y = Math.min(...boxes.map((b) => b.y));
  const r = Math.max(...boxes.map((b) => b.x + b.width)), btm = Math.max(...boxes.map((b) => b.y + b.height));
  return { x: Math.max(0, x - 8), y: Math.max(0, y - 8), width: Math.min(r - x + 16, p.viewportSize().width), height: Math.min(btm - y + 16, maxH || 99999) };
}
for (const [w, tag] of [[1440, "d"], [390, "m"]]) {
  const ctx = await b.newContext({ viewport: { width: w, height: 900 }, isMobile: w < 600, hasTouch: w < 600, deviceScaleFactor: w < 600 ? 2 : 1 });
  await ctx.addCookies([{ name: "nxeon_cookie_consent", value: "necessary", domain: "127.0.0.1", path: "/" }]);
  const p = await ctx.newPage();
  const errs = []; p.on("pageerror", (e) => errs.push(e.message)); p.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text()); });
  const res = await p.goto(URL, { waitUntil: "networkidle", timeout: 600000 });
  console.log(tag, "status", res.status());
  await p.addStyleTag({ content: hide });
  await settle(p);
  const sw = await p.evaluate(() => [document.documentElement.scrollWidth, document.documentElement.clientWidth]);
  console.log(tag, "scrollWidth/clientWidth", sw.join("/"));
  await p.screenshot({ path: `${OUT}/full-${tag}.jpg`, fullPage: true, quality: 78, type: "jpeg" });
  await p.locator("#top").screenshot({ path: `${OUT}/hero-${tag}.jpg`, quality: 88, type: "jpeg" });
  await p.locator("#hardware").screenshot({ path: `${OUT}/infrastructure-${tag}.jpg`, quality: 88, type: "jpeg" });
  if (w < 600) { await p.click("#dd-ftoggle"); await p.waitForTimeout(300); }
  await p.locator(".dd-classes").scrollIntoViewIfNeeded(); await p.waitForTimeout(400);
  await p.screenshot({ path: `${OUT}/filter-cards-${tag}.jpg`, quality: 88, type: "jpeg", fullPage: true, clip: await clipOf(p, [".dd-classes", "#dd-filter", ".dd-bar"]) });
  if (w < 600) { await p.click("#dd-ftoggle"); await p.waitForTimeout(300); }
  await p.screenshot({ path: `${OUT}/cards-${tag}.jpg`, quality: 88, type: "jpeg", fullPage: true, clip: await clipOf(p, ["#dd-grid"], w < 600 ? 1500 : 1240) });
  // hover state on the first card (lift + render scale)
  if (w >= 600) { await p.hover("#dd-grid > li:first-child"); await p.waitForTimeout(700); await p.locator("#dd-grid > li:first-child").screenshot({ path: `${OUT}/card-hover-${tag}.jpg`, quality: 90, type: "jpeg" }); await p.mouse.move(0, 0); }
  // list view
  await p.click('.dd-seg [data-view="list"]'); await p.waitForTimeout(600);
  if (w < 600) { await p.click("#dd-ftoggle"); await p.waitForTimeout(300); }
  await p.screenshot({ path: `${OUT}/list-${tag}.jpg`, quality: 88, type: "jpeg", fullPage: true, clip: await clipOf(p, [".dd-layout"], w < 600 ? 2600 : 1300) });
  const sw2 = await p.evaluate(() => document.documentElement.scrollWidth);
  console.log(tag, "list scrollWidth", sw2);
  // a filter interaction: AMD from the showcase
  await p.click('.dd-seg [data-view="cards"]');
  await p.click('.dd-v-go[data-brand="AMD"]'); await p.waitForTimeout(900);
  console.log(tag, "after AMD click:", await p.locator("#dd-count").innerText());
  await p.evaluate(() => { try { localStorage.removeItem("bm-view"); } catch {} });
  console.log(tag, "errors", JSON.stringify(errs.slice(0, 8)));
  await ctx.close();
}
// reduced motion: nothing hidden, no animation class
{
  const ctx = await b.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: "reduce" });
  const p = await ctx.newPage(); await p.goto(URL, { waitUntil: "networkidle", timeout: 600000 });
  console.log("reduced-motion: dd-anim =", await p.evaluate(() => document.getElementById("main").classList.contains("dd-anim")),
    "plate animation =", await p.evaluate(() => getComputedStyle(document.querySelector(".dd-plate")).animationName));
  await ctx.close();
}
await b.close();
EOF
