8e430a4120 Merge branch 'feature/bm-v2' into feature/bm-v2-marketing
2d61824884 Bare metal: Ultra size, GPU size set, GPU lineup with sold-out + restock alerts
/**
 * PURE + client-safe: which of the owner's server renders a bare-metal build
 * gets. Two sets, each sliced onto ONE shared transparent canvas per set and
 * bottom-aligned, so shown in equal boxes they keep their true relative size:
 * a bigger machine always looks bigger (public/nx/art/bm/README.md).
 *
 * CPU builds, public/nx/art/bm/tier-{1..4}.webp:
 *   4 Ultra   48+ cores
 *   3 Large   24-47 cores
 *   2 Medium  8-23 cores
 *   1 Small   fewer than 8 cores
 *
 * GPU builds (a GPU is fitted), public/nx/art/bm/gpu-{1..5}.webp, by GPU count:
 *   1 -> 1 GPU, 2 -> 2, 3 -> 3-4, 4 -> 5-7, 5 -> 8+
 *
 * Used by the portal catalogue, My Services and the NXM marketing page, so the
 * same build gets the same picture everywhere.
 */
export type SizeTier = 1 | 2 | 3 | 4;
export type GpuTier = 1 | 2 | 3 | 4 | 5;

export const SIZE_TIERS: SizeTier[] = [1, 2, 3, 4];
export const GPU_TIERS: GpuTier[] = [1, 2, 3, 4, 5];
export const SIZE_NAME: Record<SizeTier, string> = { 1: "Small", 2: "Medium", 3: "Large", 4: "Ultra" };
/** What each GPU size holds, for labels ("2 GPUs"). */
export const GPU_TIER_LABEL: Record<GpuTier, string> = { 1: "1 GPU", 2: "2 GPUs", 3: "3–4 GPUs", 4: "5–7 GPUs", 5: "8+ GPUs" };

/** CPU size by core count (GPU builds still get one, for anything that only shows CPU sizes). */
export function sizeTier(b: { cores: number }): SizeTier {
  if (b.cores >= 48) return 4;
  if (b.cores >= 24) return 3;
  if (b.cores >= 8) return 2;
  return 1;
}

/** "2x NVIDIA L4" -> 2; "NVIDIA A100" -> 1; null/empty -> 0. */
export function gpuCount(gpu: string | null | undefined): number {
  if (!gpu) return 0;
  const m = /^\s*(\d+)\s*[x×]/i.exec(gpu);
  return m ? Math.max(1, Number(m[1])) : 1;
}

export function gpuTier(gpu: string | null | undefined): GpuTier | null {
  const n = gpuCount(gpu);
  if (!n) return null;
  if (n >= 8) return 5;
  if (n >= 5) return 4;
  if (n >= 3) return 3;
  return n as 1 | 2;
}

export const sizeTierArt = (t: SizeTier) => `/nx/art/bm/tier-${t}.webp`;
export const gpuTierArt = (t: GpuTier) => `/nx/art/bm/gpu-${t}.webp`;

/** The render for one build: the GPU set when a GPU is fitted, else the CPU set. */
export function buildArt(b: { cores: number; gpu?: string | null }): string {
  const g = gpuTier(b.gpu);
  return g ? gpuTierArt(g) : sizeTierArt(sizeTier(b));
}
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): the GPU lineup under the catalogue
 * hero (owner, 2026-10-08). The owner's five GPU renders stand small to large
 * (1 GPU up to 8+), each labelled with what is really in stock. When no GPU
 * build is in stock it says so plainly and offers a one-click "notify me"
 * (POST /api/dedicated/stock-alert, signed-in account email); the email goes
 * out after the next catalogue sync that finds GPU stock (lib/dedicated/stock-alerts.ts).
 */
import { useState } from "react";
import type { OrderCatalogCard } from "@/lib/dedicated/order";
import { GPU_TIERS, GPU_TIER_LABEL, gpuTier, gpuTierArt } from "@/lib/dedicated/size-tier";
import { Icon } from "@/components/nx/Icon";
import { usd } from "../ui";

export function GpuBand({ cards, onShow }: { cards: OrderCatalogCard[]; onShow: () => void }) {
  const gpu = cards.filter((c) => c.gpu && c.regions.some((r) => r.inStock));
  const tiers = GPU_TIERS.map((t) => {
    const rows = gpu.filter((c) => gpuTier(c.gpu) === t);
    return { t, n: rows.length, from: rows.length ? Math.min(...rows.map((c) => c.fromMonthlyCents)) : null };
  });
  const soldOut = gpu.length === 0;
  const [state, setState] = useState<{ k: "idle" | "busy" | "done" | "err"; msg?: string }>({ k: "idle" });

  const notify = async () => {
    setState({ k: "busy" });
    try {
      const r = await fetch("/api/dedicated/stock-alert", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ kind: "gpu" }) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "Couldn't save that right now.");
      setState({ k: "done", msg: j.email });
    } catch (e) {
      setState({ k: "err", msg: (e as Error).message });
    }
  };

  return (
    <section className="bm-gpu nx-dark-island" aria-labelledby="bm-gpu-h">
      {/* eslint-disable-next-line @next/next/no-img-element -- decorative plate */}
      <img src="/nx/plates/aurora-arc.webp" alt="" aria-hidden className="bm-gpu-plate" />
      <div className="relative grid items-center gap-6 p-6 sm:p-8 lg:grid-cols-[minmax(0,0.8fr)_minmax(0,1.4fr)]">
        <div className="flex flex-col gap-3">
          <span className="text-[11px] font-extrabold uppercase tracking-[0.22em] text-[#a3e635]">GPU servers</span>
          <h2 id="bm-gpu-h" className="text-[26px] font-extrabold leading-[1.08] tracking-[-0.03em] text-white sm:text-[30px]">Bare metal with NVIDIA GPUs.</h2>
          <p className="max-w-[46ch] text-[13.5px] leading-relaxed bm-ink-2">For AI inference, rendering and transcoding. The whole machine and every GPU in it are yours.</p>
          {soldOut ? (
            <div className="mt-1 flex flex-col gap-3">
              <span className="inline-flex w-fit items-center gap-2 rounded-full border border-amber-400/35 bg-amber-950/60 px-3 py-1 text-[12px] font-bold text-amber-200"><span className="h-[6px] w-[6px] rounded-full bg-amber-400" />Currently sold out</span>
              {state.k === "done" ? (
                <p className="flex items-center gap-2 text-[13px] text-emerald-300" role="status"><Icon name="checkcircle" size={13} tone="inherit" />You&apos;re on the list. We&apos;ll email {state.msg ?? "you"} when GPU servers are back in stock.</p>
              ) : (
                <div className="flex flex-col gap-1.5">
                  <button type="button" onClick={notify} disabled={state.k === "busy"} className="btn-deploy w-fit py-2.5 text-[13.5px]">
                    <Icon name="bellnotify" size={13} tone="inherit" />{state.k === "busy" ? "Saving…" : "Notify me when they're back in stock"}
                  </button>
                  {state.k === "err" && <p className="text-[12.5px] text-rose-300" role="alert">{state.msg}</p>}
                </div>
              )}
            </div>
          ) : (
            <button type="button" onClick={onShow} className="btn-deploy mt-1 w-fit py-2.5 text-[13.5px]">
              See {gpu.length} GPU {gpu.length === 1 ? "build" : "builds"} <span className="dep-arrow">→</span>
            </button>
          )}
        </div>
        <ol className={"grid grid-cols-5 items-end gap-2 sm:gap-3 " + (soldOut ? "opacity-70 saturate-[.7]" : "")} aria-label="GPU server sizes">
          {tiers.map((s) => (
            <li key={s.t} className="bm-hero2-size flex flex-col items-center gap-1 text-center">
