/**
 * POST /api/dedicated/stock-alert  { kind: "gpu", email?: string }
 * "Notify me when it's back in stock" (lib/dedicated/stock-alerts.ts). GATED
 * like every bare-metal surface: 404 unless the viewer may see bare metal.
 * A signed-in customer is always signed up with their account email; a
 * signed-out visitor (marketing page) must send one. Rate limited per IP.
 */
import { NextResponse, type NextRequest } from "next/server";
import { currentUser } from "@/lib/auth";
import { dedicatedAccessFor } from "@/lib/dedicated/gate";
import { createStockAlert, isStockAlertKind, validAlertEmail } from "@/lib/dedicated/stock-alerts";
import { checkRateLimit, clientIp } from "@/lib/rate-limit";

export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  const user = await currentUser().catch(() => null);
  if (!(await dedicatedAccessFor(user).catch(() => ({ allowed: false }))).allowed) return NextResponse.json({ error: "Not found" }, { status: 404 });
  const rl = checkRateLimit(`dedicated-stock-alert:${clientIp(req)}`, { max: 6, windowMs: 10 * 60_000 });
  if (!rl.ok) return NextResponse.json({ error: "Too many requests. Try again in a few minutes." }, { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } });
  let body: { kind?: unknown; email?: unknown } = {};
  try { body = await req.json(); } catch { /* empty body */ }
  if (!isStockAlertKind(body.kind)) return NextResponse.json({ error: "Unknown stock alert." }, { status: 400 });
  const email = user?.email ?? (validAlertEmail(body.email) ? String(body.email).trim() : null);
  if (!email) return NextResponse.json({ error: "Enter a valid email address." }, { status: 400 });
  try {
    await createStockAlert({ email, kind: body.kind, userId: user?.id ?? null });
  } catch {
    return NextResponse.json({ error: "Couldn't save that right now. Try again in a moment." }, { status: 500 });
  }
  return NextResponse.json({ ok: true, email: email.trim().toLowerCase() });
}

