// node-2 only. Round 2: hero, GPU band (STATE=instock|soldout), cards at several widths + overlap check.
import { chromium } from "playwright";
import fs from "node:fs";
const BASE = process.env.BASE || "http://127.0.0.1:4212";
const URL = BASE + "/nxm/dedicated-servers";
const STATE = process.env.STATE || "instock";
const OUT = ".bmv2/out2"; fs.mkdirSync(OUT, { recursive: true });
const b = await chromium.launch({ args: ["--disable-dev-shm-usage"] });
async function open(w, opts = {}) {
  const ctx = await b.newContext({ viewport: { width: w, height: 900 }, isMobile: w < 600, hasTouch: w < 600, deviceScaleFactor: w < 600 ? 2 : 1, ...opts });
  await ctx.addCookies([{ name: "nxeon_cookie_consent", value: "necessary", domain: "127.0.0.1", path: "/" }]);
  const p = await ctx.newPage();
  p.on("pageerror", (e) => console.log("PAGEERROR", w, e.message));
  await p.goto(URL, { waitUntil: "networkidle", timeout: 600000 });
  await p.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 450) { window.scrollTo({ top: y, behavior: "instant" }); await new Promise((r) => setTimeout(r, 120)); } window.scrollTo({ top: 0, behavior: "instant" }); });
  await p.waitForTimeout(1300);
  return { ctx, p };
}
const overlap = (p) => p.evaluate(() => {
  let min = 1e9, worst = "";
  document.querySelectorAll("#dd-grid > li.dd-bcard").forEach((li) => {
    const img = li.querySelector(".dd-well-art").getBoundingClientRect();
    const src = li.querySelector(".dd-well-art").getAttribute("src");
    const inset = /tier-4/.test(src) ? 0.015 : /gpu-5/.test(src) ? 0.128 : /gpu-[34]/.test(src) ? 0.2 : /gpu-[12]/.test(src) ? 0.24 : 0.129;
    const artLeft = img.left + img.width * inset;
    let right = 0;
    li.querySelectorAll(".dd-id .dd-fam-k, .dd-id .dd-name, .dd-id .dd-cpu").forEach((el) => { const r = document.createRange(); r.selectNodeContents(el); for (const rc of r.getClientRects()) right = Math.max(right, rc.right); });
    const gap = artLeft - right;
    if (gap < min) { min = gap; worst = li.querySelector(".dd-name").textContent + " (" + src.split("/").pop() + ")"; }
  });
  return { minGapPx: Math.round(min), worst };
});
if (STATE === "instock") {
  for (const [w, tag] of [[1440, "d"], [390, "m"]]) {
    const { ctx, p } = await open(w);
    await p.locator("#top").screenshot({ path: `${OUT}/hero-${tag}.jpg`, quality: 88, type: "jpeg" });
    await p.locator("#gpu").screenshot({ path: `${OUT}/gpu-instock-${tag}.jpg`, quality: 88, type: "jpeg" });
    await p.click("[data-gpu-go]"); await p.waitForTimeout(900);
    console.log(tag, "GPU button ->", await p.locator("#dd-count").innerText(), "| pressed:", await p.locator('.dd-cls[aria-pressed="true"] .dd-cls-t').innerText());
    console.log(tag, "scrollWidth", await p.evaluate(() => document.documentElement.scrollWidth));
    await ctx.close();
  }
  for (const [w, tag] of [[1440, "d-1440"], [1280, "d-1280"], [1024, "d-1024"], [390, "m"]]) {
    const { ctx, p } = await open(w);
    console.log("cards", w, "overlap check", JSON.stringify(await overlap(p)), "scrollWidth", await p.evaluate(() => document.documentElement.scrollWidth));
    const g = p.locator("#dd-grid"); await g.scrollIntoViewIfNeeded();
    const bb = await g.boundingBox(); const sy = await p.evaluate(() => window.scrollY);
    await p.screenshot({ path: `${OUT}/cards-${tag}.jpg`, quality: 86, type: "jpeg", fullPage: true, clip: { x: 0, y: bb.y + sy - 10, width: w, height: Math.min(bb.height + 20, w < 600 ? 1700 : 1100) } });
    await ctx.close();
  }
} else {
  for (const [w, tag] of [[1440, "d"], [390, "m"]]) {
    const { ctx, p } = await open(w);
    await p.locator("#gpu").screenshot({ path: `${OUT}/gpu-soldout-${tag}.jpg`, quality: 88, type: "jpeg" });
    if (w > 600) {
      // client-side validation
      await p.click("#dd-notify button"); await p.waitForTimeout(300);
      console.log("empty submit ->", await p.locator("#dd-notify-msg").innerText());
      // the API's own error text, shown inline (a 429 from the rate limiter, simulated)
      await p.route("**/api/dedicated/stock-alert", (r) => r.fulfill({ status: 429, contentType: "application/json", body: JSON.stringify({ error: "Too many requests. Try again in a few minutes." }) }));
      await p.fill("#dd-notify-email", "owner@example.com"); await p.click("#dd-notify button"); await p.waitForTimeout(600);
      console.log("429 ->", await p.locator("#dd-notify-msg").innerText());
      await p.locator("#gpu").screenshot({ path: `${OUT}/gpu-soldout-error-${tag}.jpg`, quality: 88, type: "jpeg" });
      await p.unroute("**/api/dedicated/stock-alert");
      // the real API against the throwaway DB
      await p.click("#dd-notify button"); await p.waitForTimeout(2500);
      console.log("real POST ->", await p.locator("#dd-notify-msg").innerText());
      await p.locator("#gpu").screenshot({ path: `${OUT}/gpu-soldout-done-${tag}.jpg`, quality: 88, type: "jpeg" });
    }
    console.log(tag, "scrollWidth", await p.evaluate(() => document.documentElement.scrollWidth));
    await ctx.close();
  }
}
await b.close();
EOF
